namespace RecipeCommunity.Models;

public class RecipeCategory
{
    public string Slug { get; set; } = "";
    public string Name { get; set; } = "";
    public string Icon { get; set; } = "";
    public string Description { get; set; } = "";
}

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = "";
    public string CategorySlug { get; set; } = "";
    public List<string> Ingredients { get; set; } = [];
    public List<string> Steps { get; set; } = [];
    public int TotalRatings { get; set; }
    public int RatingSum { get; set; }

    public double AverageRating => TotalRatings == 0 ? 0 : (double)RatingSum / TotalRatings;
}

namespace RecipeCommunity.Models;

public class RecipeService
{
    private readonly List<RecipeCategory> _categories =
    [
        new() { Slug = "breakfast", Name = "Breakfast", Icon = "🥞", Description = "Start your day right" },
        new() { Slug = "lunch", Name = "Lunch", Icon = "🥗", Description = "Midday meals and salads" },
        new() { Slug = "dinner", Name = "Dinner", Icon = "🍝", Description = "Hearty evening dishes" },
        new() { Slug = "desserts", Name = "Desserts", Icon = "🍰", Description = "Sweet treats and bakes" },
    ];

    private readonly List<Recipe> _recipes;
    private int _nextId;

    public RecipeService()
    {
        _recipes =
        [
            new()
            {
                Id = 1, Title = "Classic Pancakes", CategorySlug = "breakfast",
                Ingredients = ["2 cups flour", "2 eggs", "1½ cups milk", "3 tbsp sugar", "1 tsp baking powder"],
                Steps = ["Mix dry ingredients.", "Whisk in eggs and milk.", "Cook on a greased griddle until golden."],
                TotalRatings = 12, RatingSum = 50
            },
            new()
            {
                Id = 2, Title = "Avocado Toast", CategorySlug = "breakfast",
                Ingredients = ["2 slices sourdough", "1 ripe avocado", "Salt & pepper", "Red pepper flakes"],
                Steps = ["Toast bread.", "Mash avocado and spread on toast.", "Season to taste."],
                TotalRatings = 8, RatingSum = 35
            },
            new()
            {
                Id = 3, Title = "Caesar Salad", CategorySlug = "lunch",
                Ingredients = ["1 head romaine", "¼ cup parmesan", "Croutons", "Caesar dressing"],
                Steps = ["Chop romaine.", "Toss with dressing, parmesan, and croutons."],
                TotalRatings = 6, RatingSum = 26
            },
            new()
            {
                Id = 4, Title = "Spaghetti Bolognese", CategorySlug = "dinner",
                Ingredients = ["400g spaghetti", "500g ground beef", "1 can crushed tomatoes", "1 onion", "2 cloves garlic"],
                Steps = ["Cook spaghetti.", "Sauté onion and garlic, brown beef.", "Add tomatoes and simmer 20 min.", "Serve over pasta."],
                TotalRatings = 15, RatingSum = 68
            },
            new()
            {
                Id = 5, Title = "Chocolate Lava Cake", CategorySlug = "desserts",
                Ingredients = ["200g dark chocolate", "100g butter", "2 eggs", "2 egg yolks", "¼ cup sugar", "2 tbsp flour"],
                Steps = ["Melt chocolate and butter.", "Whisk eggs, yolks, and sugar.", "Fold in chocolate mixture and flour.", "Bake at 425°F for 12 min."],
                TotalRatings = 20, RatingSum = 95
            },
        ];
        _nextId = 6;
    }

    public List<RecipeCategory> GetCategories() => _categories;

    public RecipeCategory? GetCategory(string slug) =>
        _categories.FirstOrDefault(c => c.Slug == slug);

    public List<Recipe> GetRecipesByCategory(string slug) =>
        _recipes.Where(r => r.CategorySlug == slug).ToList();

    public Recipe? GetRecipe(int id) =>
        _recipes.FirstOrDefault(r => r.Id == id);

    public void AddRating(int recipeId, int stars)
    {
        var recipe = GetRecipe(recipeId);
        if (recipe is null || stars is < 1 or > 5) return;
        recipe.TotalRatings++;
        recipe.RatingSum += stars;
    }

    public Recipe AddRecipe(string title, string categorySlug, List<string> ingredients, List<string> steps)
    {
        var recipe = new Recipe
        {
            Id = _nextId++,
            Title = title,
            CategorySlug = categorySlug,
            Ingredients = ingredients,
            Steps = steps
        };
        _recipes.Add(recipe);
        return recipe;
    }
}

