arguments.file_text:
@page "/recipes/{CategorySlug}"
@inject RecipeCommunity.Models.RecipeService RecipeService

<PageTitle>@(category?.Name ?? "Recipes")</PageTitle>

@if (category is null)
{
    <h3>Category not found.</h3>
}
else
{
    <h2>@category.Icon @category.Name Recipes</h2>
    <p class="text-muted">@category.Description</p>

    var recipes = RecipeService.GetRecipesByCategory(CategorySlug!);

    @if (recipes.Count == 0)
    {
        <div class="alert alert-info">No recipes in this category yet. <a href="submit">Be the first to add one!</a></div>
    }
    else
    {
        <div class="list-group">
            @foreach (var recipe in recipes)
            {
                <a href="recipe/@recipe.Id" class="list-group-item list-group-item-action d-flex justify-content-between align-items-center">
                    <span><strong>@recipe.Title</strong></span>
                    <span class="badge bg-warning text-dark rounded-pill">
                        ⭐ @(recipe.TotalRatings > 0 ? recipe.AverageRating.ToString("0.0") : "—")
                    </span>
                </a>
            }
        </div>
    }

    <a href="/" class="btn btn-outline-secondary mt-3">← Back to categories</a>
}

@code {
    [Parameter] public string? CategorySlug { get; set; }

    private RecipeCommunity.Models.RecipeCategory? category;

    protected override void OnParametersSet()
    {
        category = CategorySlug is not null ? RecipeService.GetCategory(CategorySlug) : null;
    }
}

@page "/recipe/{Id:int}"
@inject RecipeCommunity.Models.RecipeService RecipeService

<PageTitle>@(recipe?.Title ?? "Recipe")</PageTitle>

@if (recipe is null)
{
    <h3>Recipe not found.</h3>
}
else
{
    <h2>@recipe.Title</h2>

    <p class="text-muted">
        Category:
        @{ var cat = RecipeService.GetCategory(recipe.CategorySlug); }
        <a href="recipes/@recipe.CategorySlug">@(cat?.Icon) @(cat?.Name)</a>
    </p>

    <div class="mb-4">
        <StarRating RecipeId="recipe.Id" CurrentAverage="recipe.AverageRating" TotalRatings="recipe.TotalRatings" />
    </div>

    <div class="row">
        <div class="col-md-5">
            <div class="card mb-3">
                <div class="card-header"><strong>Ingredients</strong></div>
                <ul class="list-group list-group-flush">
                    @foreach (var ing in recipe.Ingredients)
                    {
                        <li class="list-group-item">@ing</li>
                    }
                </ul>
            </div>
        </div>
        <div class="col-md-7">
            <div class="card mb-3">
                <div class="card-header"><strong>Steps</strong></div>
                <ol class="list-group list-group-flush list-group-numbered">
                    @foreach (var step in recipe.Steps)
                    {
                        <li class="list-group-item">@step</li>
                    }
                </ol>
            </div>
        </div>
    </div>

    <a href="recipes/@recipe.CategorySlug" class="btn btn-outline-secondary">← Back to @(cat?.Name)</a>
}

@code {
    [Parameter] public int Id { get; set; }

    private RecipeCommunity.Models.Recipe? recipe;

    protected override void OnParametersSet()
    {
        recipe = RecipeService.GetRecipe(Id);
    }
}

@page "/submit"
@rendermode InteractiveServer
@inject RecipeCommunity.Models.RecipeService RecipeService
@inject NavigationManager Navigation

<PageTitle>Submit a Recipe</PageTitle>

<h2>📝 Submit a Recipe</h2>

<EditForm Model="model" OnValidSubmit="HandleSubmit" FormName="submitRecipe">
    <DataAnnotationsValidator />
    <ValidationSummary class="text-danger" />

    <div class="mb-3">
        <label class="form-label">Title</label>
        <InputText class="form-control" @bind-Value="model.Title" />
        <ValidationMessage For="() => model.Title" />
    </div>

    <div class="mb-3">
        <label class="form-label">Category</label>
        <InputSelect class="form-select" @bind-Value="model.CategorySlug">
            <option value="">-- select --</option>
            @foreach (var cat in RecipeService.GetCategories())
            {
                <option value="@cat.Slug">@cat.Icon @cat.Name</option>
            }
        </InputSelect>
        <ValidationMessage For="() => model.CategorySlug" />
    </div>

    <div class="mb-3">
        <label class="form-label">Ingredients (one per line)</label>
        <InputTextArea class="form-control" rows="5" @bind-Value="model.IngredientsRaw" />
        <ValidationMessage For="() => model.IngredientsRaw" />
    </div>

    <div class="mb-3">
        <label class="form-label">Steps (one per line)</label>
        <InputTextArea class="form-control" rows="5" @bind-Value="model.StepsRaw" />
        <ValidationMessage For="() => model.StepsRaw" />
    </div>

    <button type="submit" class="btn btn-primary">Submit Recipe</button>
    <a href="/" class="btn btn-outline-secondary ms-2">Cancel</a>
</EditForm>

@code {
    private RecipeFormModel model = new();

    private void HandleSubmit()
    {
        var ingredients = model.IngredientsRaw!
            .Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
            .ToList();

        var steps = model.StepsRaw!
            .Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
            .ToList();

        var recipe = RecipeService.AddRecipe(model.Title!, model.CategorySlug!, ingredients, steps);
        Navigation.NavigateTo($"recipe/{recipe.Id}");
    }

    private class RecipeFormModel
    {
        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Title is required.")]
        public string? Title { get; set; }

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Pick a category.")]
        public string? CategorySlug { get; set; }

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Add at least one ingredient.")]
        public string? IngredientsRaw { get; set; }

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Add at least one step.")]
        public string? StepsRaw { get; set; }
    }
}

@rendermode InteractiveServer
@inject RecipeCommunity.Models.RecipeService RecipeService

<div class="d-inline-block">
    <span class="me-2">
        @for (int i = 1; i <= 5; i++)
        {
            var star = i;
            <span role="button"
                  style="font-size:1.5rem; cursor:pointer; color:@(star <= (hoveredStar ?? 0) ? "#ffc107" : (star <= Math.Round(CurrentAverage) ? "#ffc107" : "#ccc"))"
                  @onclick="() => SubmitRating(star)"
                  @onmouseover="() => hoveredStar = star"
                  @onmouseout="() => hoveredStar = null">★</span>
        }
    </span>
    <small class="text-muted">
        @if (submitted)
        {
            <span class="text-success">Thanks for rating!</span>
        }
        else if (TotalRatings > 0)
        {
            @($"{CurrentAverage:0.0} ({TotalRatings} ratings)")
        }
        else
        {
            <span>No ratings yet</span>
        }
    </small>
</div>

@code {
    [Parameter] public int RecipeId { get; set; }
    [Parameter] public double CurrentAverage { get; set; }
    [Parameter] public int TotalRatings { get; set; }

    private int? hoveredStar;
    private bool submitted;

    private void SubmitRating(int stars)
    {
        RecipeService.AddRating(RecipeId, stars);
        var recipe = RecipeService.GetRecipe(RecipeId);
        if (recipe is not null)
        {
            CurrentAverage = recipe.AverageRating;
            TotalRatings = recipe.TotalRatings;
        }
        submitted = true;
    }
}

